-- Import: Bootslogbuch-Sandbox.xlsx
-- Target boat: Daniela | 80 trips and 45 cost entries
-- Source IDs are replaced by UUIDs generated by PostgreSQL.
-- This script executes only when the target boat is empty.

do $import$
declare
  target_boat_id uuid;
  import_user_id uuid;
  matching_boats integer;
begin
  select count(*) into matching_boats from public.boats where name = 'Daniela';
  if matching_boats <> 1 then
    raise exception 'Exactly one boat named Daniela is required (found: %).', matching_boats;
  end if;

  select id, created_by into target_boat_id, import_user_id from public.boats where name = 'Daniela';
  if exists (select 1 from public.trips where boat_id = target_boat_id)
     or exists (select 1 from public.costs where boat_id = target_boat_id) then
    raise exception 'Boat Daniela is not empty. Import was not run.';
  end if;


end;
$import$;
